qPriceSync = (original => function(p) {const r=p&&p.qRevs&&p.qRevs[p.qRevs.length-1];if(r&&r.issuedQuote){if(p.status==='quote')p.price=r.issuedQuote.amount;return;}return original.apply(this,arguments);})(qPriceSync);
