  if (!d || !d.name.trim()) errors.push('اكتب اسم المشروع');
  if (!d || !d.client.trim()) errors.push('حدّد العميل');
  if (!d || !(d.amount > 0)) errors.push('أدخل قيمة موجبة للعرض');
  if (!d || !d.scope.trim()) errors.push('اكتب نطاق العمل الخاص بهذه النسخة');
  if (!d || !/^\d{4}-\d{2}-\d{2}$/.test(d.date) || isNaN(Date.parse(d.date))) errors.push('حدّد تاريخ العرض');
