    items.filter(x=>!x.pv&&w146SameSpace(x)&&x.project&&!P.some(p=>normN(p.name)===normN(x.project))).forEach(x=>{if(!unique.has(normN(x.project))){unique.set(normN(x.project),1);rows.push({value:x.project,detail:'اسم مسجل في المهام؛ بيانات المشروع غير مكتملة'})}});
