statsFor=function(uid){const t=today(),ws=iso(weekStart()),we=iso(addDays(weekStart(),6)),mine=allItems.filter(x=>(x.owner||ME?.id)===uid&&x.kind!=='meeting'&&x.space!=='p'&&!x.pv),open=mine.filter(x=>!x.done),late=open.filter(x=>x.due&&x.due<t),wait=open.filter(x=>x.kind==='follow'||x.status==='waiting').length,doneW=mine.filter(x=>x.done&&x.doneAt&&iso(new Date(x.doneAt))>=ws&&iso(new Date(x.doneAt))<=we).length,eligible=open.filter(x=>x.due&&x.due<=we).length;return {open:open.length,late:late.length,wait,doneW,pct:doneW+eligible?Math.round(doneW/(doneW+eligible)*100):0,lateList:late}};
teamView=(f=>function(){if(PRIV())return '<div class="panel empty">متابعة الفريق متاحة في مساحة العمل.</div>';const box=document.createElement('div');box.innerHTML=f.apply(this,arguments);if(!can('team'))return box.innerHTML;const cards=[...box.querySelectorAll('.ucard')];cards.forEach(card=>{const uid=card.querySelector('[data-view]')?.dataset.view,u=USERS.find(u=>u.id===uid),s=statsFor(uid),words=normA(O148.teamQ).split(/\s+/).filter(Boolean);if(!words.every(w=>normA([u?.name,orgLine(u||{})].join(' ')).includes(w))||O148.teamState==='late'&&!s.late||O148.teamState==='wait'&&!s.wait){card.remove();return}card.querySelector('.bar')?.setAttribute('title','نسبة الإنجاز من البنود المنجزة هذا الأسبوع والمفتوحة المجدولة حتى نهايته');const contact=card.querySelector('.contact');if(contact)contact.insertAdjacentHTML('beforebegin',`<p class="o148-team-next">${s.late?'الأولوية: مراجعة '+s.late+' مهمة متأخرة':s.wait?'الأولوية: متابعة الردود المعلقة':'لا مهام متأخرة مسجلة'}</p>`)});const assign=box.querySelector('#assignForm')?.closest('.panel');if(assign){const fold=document.createElement('details');fold.className='o148-fold';fold.innerHTML='<summary>＋ إسناد مهمة جديدة للفريق</summary>';assign.before(fold);fold.append(assign)}return `<div class="o148-page"><div class="o148-tools"><input data-o148teamq placeholder="ابحث بالاسم أو الفرع أو القسم…" value="${esc(O148.teamQ)}"><select data-o148teamstate><option value="">كل الفريق</option><option value="late" ${O148.teamState==='late'?'selected':''}>لديه مهام متأخرة</option><option value="wait" ${O148.teamState==='wait'?'selected':''}>لديه انتظار رد</option></select></div><p class="sub">«مفتوحة» تشمل المهام القادمة وغير المجدولة، و«منجزة» تخص الأسبوع الحالي. المهام الخاصة مستبعدة.</p>${box.innerHTML}</div>`})(teamView);
