bkK=function(A){const S=(a,f)=>a.reduce((s,x)=>s+f(x),0),won=A.filter(x=>['award','collect','done'].includes(x.st));return {n:A.length,nego:A.filter(x=>x.st==='nego').length,won:won.length,wonV:S(won,x=>num(x.r.val)),cm:S(won,x=>x.cm),coll:S(won,x=>num(x.r.coll)),rem:S(won,x=>Math.max(0,x.cm-num(x.r.coll))),late:A.filter(x=>brkDue(x.r)).length,conv:A.length?Math.round(won.length/A.length*100):0,expected:S(A.filter(x=>!['award','collect','done','lost'].includes(x.st)),x=>x.cm),advance:S(A.filter(x=>!['award','collect','done'].includes(x.st)),x=>num(x.r.coll))}};
bkKpis=(f=>function(A){const K=bkK(A);return f.apply(this,arguments)+`<p class="o148-note">العمولات المستحقة والمحصّلة أعلاه تخص الترسيات. قبل الترسية: ${money(K.expected)} ر.س عمولات متوقعة${K.advance?' · تحصيل مسجل خارج الترسيات: '+money(K.advance)+' ر.س':''}. نسبة التحويل = الترسيات ÷ كل التعريفات.</p>`})(bkKpis);
function o148BrokerIssue(next,old){const changed=!old||['val','pct','coll'].some(k=>num(next[k])!==num(old[k]));if(!changed)return '';const val=Number(next.val||0),pct=Number(next.pct||0),paid=Number(next.coll||0);if(![val,pct,paid].every(Number.isFinite)||val<0||pct<0||pct>100||paid<0)return 'راجع قيمة العقد ونسبة العمولة والمحصّل؛ النسبة بين 0 و100';if(paid>val*pct/100+.005)return 'المحصّل يتجاوز العمولة المحسوبة؛ راجع القيمة والنسبة';return ''}
