function j149Icon(kind){const paths={task:'M8 4h8l3 3v13H5V4h3M9 11h6M9 15h4M9 4V2h6v2',phone:'M6 3h4l1 5-3 2c1 3 3 5 6 6l2-3 5 1v4c0 2-2 3-4 3C9 20 4 15 3 7c0-2 1-4 3-4',folder:'M3 6h7l2 2h9v12H3V6',arrow:'m9 5 7 7-7 7',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6'};return '<svg class="j149-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[kind]||paths.task)+'"/></svg>'}
function j149Tasks(p){return allItems.filter(x=>w146SameSpace(x)&&!x.pv&&!['meeting','note','idea'].includes(x.kind)&&tkProj(x)?.id===p.id)}
function j149Task(id){return allItems.find(x=>x.id===id&&w146SameSpace(x)&&!x.pv)||items.find(x=>x.id===id&&w146SameSpace(x))}
function j149Can(x){return !!(x&&canWrite&&own(x))}
function j149Last(p){return (p.qTrack||[]).map((x,i)=>({x,i})).filter(o=>o.x.date).sort((a,b)=>String(b.x.date).localeCompare(String(a.x.date))||b.i-a.i)[0]?.x}
qAutoNext=(f=>function(p){if(p.status!=='quote')return f(p);if(num(p.qEvery)===-1)return '';if(p.qFollowUndated){const last=j149Last(p);return last?.date?iso(addDays(parse(last.date),num(p.qEvery)>0?num(p.qEvery):7)):f(p)}const last=j149Last(p);return last?.next?(p.qSnooze&&p.qSnooze>last.next?p.qSnooze:last.next):f(p)})(qAutoNext);
function j149Due(p){return p.status==='quote'?qAutoNext(p):p.contactNext||''}
function j149FollowOwner(p){return uname(p.qFollowOwner)||p.qFollowOwner||w146Owner(p)||''}
async function j149WriteTask(id,patch,isNew=false){
 const run=(Q[id]||Promise.resolve()).then(async()=>{const current=store[id]||j149Task(id);if(!isNew&&!j149Can(current))throw Error('ليست لديك صلاحية تعديل المهمة');const next=w146TaskRefs({...q142Copy(current||{}),...patch});if(PRIV()){next.space='p';next.owner=ME.id;delete next.assignedBy}const r=await call('saveItem',{id,...next});store[id]=next;if(r?.todo!==undefined)store[id].todo=r.todo;emit();saveCache();return r});Q[id]=run.catch(()=>{});return run;
}
