function j149Cards(p,W){return `<div class="j149-taskcards">${W.map(x=>`<article class="j149-task ${!x.done&&x.due&&x.due<today()?'j149-overdue':''}"><div class="j149-head"><b>${esc(x.title)}</b><span data-state="${x.done?'done':wfReq(x)?'review':x.status||'todo'}">${x.done?'منجزة':wfReq(x)?.type==='done'?'بانتظار اعتماد الإنجاز':x.status==='waiting'?'بانتظار رد':x.status==='doing'?'جاري العمل':'لم تبدأ'}</span></div><p>${x.kind==='follow'?'الرد من':'المسؤول عن التنفيذ'}: <b>${esc(t145Owner(x))}</b>${x.from&&uname(x.owner)&&normN(x.from)!==normN(uname(x.owner))?`<small>حساب المتابعة: ${esc(uname(x.owner))}</small>`:''}</p><p>التسليم: ${x.due?esc(nice(x.due)):'لم يحدد'}${!x.done&&x.due&&x.due<today()?' · متأخر':''}${x.deliverable?`<small>المخرج المطلوب: ${esc(x.deliverable)}</small>`:'<small>المخرج المطلوب غير موثق؛ حدده قبل التنفيذ.</small>'}</p>${x.workUpdate?`<p class="j149-update">آخر تحديث: ${esc(x.workUpdate.text)}<small>${esc(x.workUpdate.date||'')}</small></p>`:''}<div class="row2">${j149QuickButton(x)}<button type="button" class="btn ghost xs" data-j149open="${esc(x.id)}">التفاصيل والملفات</button></div></article>`).join('')||'<p class="sub">لا توجد مهام في هذا النطاق.</p>'}</div>`}
wkView=(f=>function(p,c,W){W=j149Tasks(p);const box=document.createElement('div');box.innerHTML=f.call(this,p,c,W);const table=box.querySelector('.wkt')?.closest('.tblwrap');table?.remove();const host=box.querySelector('#sec-wk');if(!host)return box.innerHTML;host.querySelector('.empty')?.remove();const selected=W.filter(x=>wkF==='all'||(wkF==='done'?x.done:!x.done)).sort((a,b)=>Number(a.done)-Number(b.done)||String(a.due||'9').localeCompare(String(b.due||'9')));host.insertAdjacentHTML('beforeend',j149Cards(p,selected));const form=host.querySelector('#ptaskForm');if(form){form.dataset.j149Project=p.id;form.querySelector('[name="title"]').required=true;form.querySelector('[name="due"]').required=true;form.insertAdjacentHTML('beforeend','<label class="j149-deliverable">ما الذي سيسلمه المهندس؟ *<textarea name="deliverable" required rows="2" placeholder="مثال: مخطط إنشائي PDF وDWG للمراجعة الداخلية"></textarea></label>');const owners=form.querySelector('[name="owner"]');if(owners&&!can('assign')){owners.value=ME.id;owners.disabled=true}const d=document.createElement('details');d.className='j149-add';d.innerHTML='<summary>＋ تكليف جديد مرتبط بالمشروع</summary>';form.before(d);const chips=host.querySelector('.wkq');if(chips)d.append(chips);d.append(form)}host.insertAdjacentHTML('afterbegin','<p class="sub">هذه نفس مهام اليوم، وليست نسخة أخرى. إنجاز مهمة لا يعتمد الخطوة الفنية تلقائيًا؛ راجع المخرج أولًا.</p>');return box.innerHTML})(wkView);
row=(f=>function(x){const box=document.createElement('div');box.innerHTML=f.apply(this,arguments);const a=box.querySelector('.acts');if(a&&j149Can(x))a.insertAdjacentHTML('afterbegin',j149QuickButton(x));return box.innerHTML})(row);
function j149OpenTask(x){if(!j149Can(x))return;const req=wfReq(x);modal('j149Task',`<h2>تحديث المهمة</h2><p>${esc(x.title)}</p><p class="sub">${esc(x.project||'بدون مشروع')} · الموعد: ${x.due?esc(nice(x.due)):'غير محدد'} · حساب المتابعة: ${esc(uname(x.owner)||'غير محدد')}</p>${req?`<p class="j149-warning">يوجد طلب ${esc(WFT[req.type]||req.type)} بانتظار الموافقة؛ يمكنك تسجيل مستجد دون استبدال الطلب.</p>`:''}<form data-j149taskform="${esc(x.id)}"><label>المسؤول عن التنفيذ<input name="from" value="${esc(x.from||uname(x.owner)||'')}"></label><label>المخرج المطلوب تسليمه<textarea name="deliverable" rows="2">${esc(x.deliverable||'')}</textarea></label><label>آخر مستجد / سبب التعطل أو مرجع التسليم *<textarea name="update" required rows="3" placeholder="مثال: تم تجهيز المعماري وبانتظار مراجعة الإنشائي"></textarea></label><label>الحالة<select name="state"><option value="keep">تسجيل مستجد فقط</option><option value="doing" ${!x.done&&!req?'':'disabled'}>بدأت / جاري العمل</option><option value="waiting" ${!x.done&&!req?'':'disabled'}>بانتظار رد أو مستند</option><option value="done" ${!x.done&&!req?'':'disabled'}>${wfOf(x).strict&&!canAp(x)?'إرسال لاعتماد الإنجاز':'تسجيل إنجاز المهمة'}</option></select></label><p class="sub">هذا لا يغيّر حساب الموظف أو موعد التسليم. تغييرهما من تفاصيل المهمة وفق الصلاحيات والموافقات.</p><div class="auth-err" data-j149error></div><div class="row2"><button class="btn gold">حفظ التحديث</button><button type="button" class="btn ghost" data-mx>إلغاء</button></div></form>`)}
function j149TaskChange(x,F){if(!j149Can(x))throw Error('ليس لديك صلاحية تعديل هذه المهمة');const text=String(F.update||'').trim();if(!text)throw Error('اكتب آخر مستجد');const state=F.state||'keep';if(!['keep','doing','waiting','done'].includes(state))throw Error('راجع الحالة');if(state!=='keep'&&(x.done||wfReq(x)))throw Error('يوجد إنجاز أو طلب موافقة؛ سجل مستجدًا فقط');const d={from:String(F.from||'').trim(),deliverable:String(F.deliverable||'').trim(),workUpdate:{text,date:today(),at:Date.now(),by:ME.id},note:(x.note?x.note+'\n':'')+today()+' — '+text};if(state==='done'){if(wfOf(x).strict&&!canAp(x)){d.wf={...q142Copy(wfOf(x)),req:{type:'done',note:text,at:Date.now(),by:ME.id,ap:x.assignedBy||''},hist:wfHist(x,{t:'req',type:'done'})}}else if(x.status==='daily')throw Error('المتابعة اليومية تُغلق من زرها المعتاد حتى يحدد موعد تكرارها');else Object.assign(d,{done:true,doneAt:Date.now(),status:'todo'})}else if(state!=='keep'){d.status=state}return d}
document.addEventListener('submit',async e=>{const form=e.target.closest?.('[data-j149taskform]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const error=form.querySelector('[data-j149error]'),button=form.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{const x=j149Task(form.dataset.j149taskform),F=Object.fromEntries(new FormData(form));await j149WriteTask(x.id,j149TaskChange(x,F));document.getElementById('j149Task').hidden=true;render();if(cliEdit)drawCli();j149Saved('✓ حُفظ تحديث المهمة؛ يظهر في اليوم والمشروع')}catch(x){error.textContent=x.message||'تعذر الحفظ؛ بقيت البيانات أمامك لإعادة المحاولة'}finally{button.disabled=false}},true);
