document.addEventListener('submit',async e=>{if(e.target.id!=='ptaskForm'||!e.target.elements.deliverable)return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,p=w146Current(),F=Object.fromEntries(new FormData(form)),owner=F.owner||ME.id;if(!p||!canWrite)return;const title=String(F.title||'').trim(),deliverable=String(F.deliverable||'').trim();if(!title||!deliverable||!f144Date(F.due))return toast('أكمل عنوان المهمة والمخرج وتاريخ التسليم',true);if(owner!==ME.id&&(!can('assign')||!scopeUsers().some(u=>u.id===owner&&u.active!==false)))return toast('لا يمكنك الإسناد لهذا الحساب',true);const b=form.querySelector('button');b.disabled=true;try{await j149WriteTask(rid(),{kind:'task',title,deliverable,commissionedBy:String(F.commissionedBy||'').trim(),due:F.due,done:false,doneAt:null,createdAt:Date.now(),note:'',priority:0,ttype:'tech',status:'todo',project:p.name,projectId:p.id,client:p.client||'',space:p.space||'',owner,from:uname(owner)||ME.name,wtype:F.wtype||'other',phase:F.phase||'',...(owner!==ME.id?{assignedBy:ME.id,wf:{strict:true,acc:'pending'}}:{})},true);delete J149.drafts[SPACE+':'+p.id];J149.open[SPACE+':'+p.id]=false;J149.ignore=p.id;wkF='open';render();j149Saved('✓ أضيفت مهمة واحدة؛ تظهر في اليوم والمشروع')}catch(x){toast('تعذر الحفظ: '+x.message,true)}finally{b.disabled=false}},true);
function j149OpenFollow(p){if(!p||!pEdit()||p.status!=='quote')return;const tasks=j149Tasks(p).filter(x=>!x.done&&j149Can(x)&&x.kind==='follow'),users=scopeUsers().filter(u=>u.active!==false&&(can('assign')||u.id===ME.id)),last=j149Last(p),linked=tasks.find(x=>x.id===p.qFollowTaskId)||(tasks.length===1?tasks[0]:null);modal('j149Follow',`<h2>تحديث متابعة العرض</h2><p>${esc(p.name)} · ${esc(p.code||p.id)}</p><p class="sub">آخر تواصل: ${last?esc(last.date+' — '+(last.text||'بدون ملخص')):'لم يسجل'} · تسجيل داخلي؛ لا يرسل رسالة للعميل.</p><form data-j149followform="${esc(p.id)}"><div class="j149-grid"><label>تاريخ التواصل *<input type="date" name="date" required max="${today()}" value="${today()}"></label><label>الوسيلة<select name="kind">${QTK.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>تواصلت مع<input name="who" value="${esc(last?.who||linked?.from||'')}" placeholder="اسم ممثل العميل"></label><label>موعد المتابعة القادمة (اختياري)<input name="next" type="date" min="${today()}" value="${j149Due(p)>=today()?esc(j149Due(p)):''}"></label><label>حساب مسؤول المتابعة<select name="owner">${users.map(u=>`<option value="${esc(u.id)}" ${u.id===(p.qFollowOwner||linked?.owner||ME.id)?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>مرحلة العرض<select name="stage">${QSS.filter(x=>!['won','lost'].includes(x[0])).map(([k,l])=>`<option value="${k}" ${p.qst===k?'selected':''}>${esc(l)}</option>`).join('')}</select></label></div><label>رد العميل / ملخص التواصل *<textarea name="text" required rows="3" placeholder="مثال: طلب تعديل نطاق الإشراف وسيرد الخميس"></textarea></label><label>ما المطلوب في المتابعة القادمة؟ *<input name="action" required value="${esc(last?.action||linked?.title||'متابعة رد العميل على العرض')}"></label><label>ربط بمهام اليوم<select name="task"><option value="">تسجيل في العرض فقط</option><option value="new" ${tasks.length?'':'selected'}>إنشاء مهمة متابعة مرتبطة</option>${tasks.map(x=>`<option value="${esc(x.id)}" ${x.id===p.qFollowTaskId||tasks.length===1?'selected':''}>تحديث المهمة الموجودة: ${esc(x.title)}</option>`).join('')}</select></label><p class="sub">اختيار مهمة موجودة يحدّث موعدها وحسابها نفسه، ولا ينشئ نسخة أخرى. الموافقة المبدئية لا تعني اعتماد العقد؛ الاعتماد يظل في مساره المعتاد.</p><div class="auth-err" data-j149error></div><div class="row2"><button class="btn gold">حفظ المتابعة</button><button type="button" class="btn ghost" data-mx>إلغاء</button></div></form>`)}
function j149FollowChange(p,F){if(!pEdit()||p.status!=='quote')throw Error('المتابعة متاحة للعروض المفتوحة فقط');if(!f144Date(F.date)||F.date>today()||F.next&&(!f144Date(F.next)||F.next<today()||F.next<F.date))throw Error('راجع تاريخ التواصل والمتابعة القادمة');if(!String(F.text||'').trim()||!String(F.action||'').trim())throw Error('اكتب رد العميل والإجراء القادم');if(!QSS.some(x=>x[0]===F.stage&&!['won','lost'].includes(x[0])))throw Error('استخدم اعتماد العقد أو الرفض من مسارهما المعتاد');if(!QTK.includes(F.kind))throw Error('راجع وسيلة التواصل');if(!scopeUsers().some(u=>u.id===F.owner&&u.active!==false)||F.owner!==ME.id&&!can('assign'))throw Error('راجع مسؤول المتابعة');qMig(p);p.qTrack.push({id:F.entryId||rid(),at:Date.now(),date:F.date,kind:F.kind,who:String(F.who||'').trim(),text:String(F.text).trim(),next:F.next,action:String(F.action).trim(),owner:F.owner});p.qFollowUndated=!F.next;if(F.next)p.qSnooze=F.next;else delete p.qSnooze;p.log=p.log||[];p.log.push({id:F.entryId||rid(),date:F.date,kind:'متابعة عرض السعر',subject:'متابعة العرض الفني والمالي',details:(F.kind||'')+(F.who?' — '+F.who:'')+' — '+String(F.text).trim()+' — '+(F.next?'المتابعة القادمة: '+F.next:'بانتظار رد العميل — تذكير المتابعة تلقائي')});p.qFollowOwner=F.owner;p.qst=F.stage;return p}
async function j149SaveProject(p,change){if(projDraft?.id===p.id&&projDirty){if(!await projSaveNow())throw Error('تعذر حفظ تعديلات المشروع الحالية؛ حاول بعد المزامنة')}const live=projDraft?.id===p.id?projDraft:PROJECTS.find(x=>x.id===p.id)||p,copy=q142Copy(live),base=live.updatedAt||0;change(copy);const r=await call('saveProject',copy,base);if(r?.merged&&r.p)Object.assign(copy,r.p);if(r?.updatedAt)copy.updatedAt=r.updatedAt;const at=PROJECTS.findIndex(x=>x.id===p.id);if(at>=0)PROJECTS[at]=q142Copy(copy);if(projDraft?.id===p.id){Object.assign(projDraft,copy);projDirty=false}Object.assign(p,copy);render();if(cliEdit)drawCli();return r}
document.addEventListener('submit',async e=>{const form=e.target.closest?.('[data-j149followform]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button:not([type]),button[type="submit"]'),error=form.querySelector('[data-j149error]');button.disabled=true;try{const p=PROJECTS.find(x=>x.id===form.dataset.j149followform&&w146SameSpace(x));if(!p)throw Error('العرض غير موجود');const F=Object.fromEntries(new FormData(form));F.entryId=form.dataset.entryId||(form.dataset.entryId=rid());const old=F.task&&F.task!=='new'?j149Task(F.task):null;if(F.task&&F.task!=='new'&&(!old||!j149Can(old)||tkProj(old)?.id!==p.id))throw Error('اختر مهمة تابعة لنفس العرض');if(old&&(wfReq(old)||wfOf(old).strict&&!canAp(old)&&old.due!==F.next))throw Error('المهمة تحتاج موافقة لتغيير الموعد؛ اختر التسجيل في العرض فقط ثم اطلب التغيير من تفاصيل المهمة');const tid=F.task==='new'?(form.dataset.taskId||(form.dataset.taskId=rid())):F.task;const preview=q142Copy(p);j149FollowChange(preview,F);await j149SaveProject(p,c=>{if(!(c.qTrack||[]).some(x=>x.id===F.entryId))j149FollowChange(c,F);if(tid)c.qFollowTaskId=tid;else delete c.qFollowTaskId});form.dataset.projectSaved='1';if(tid){const data={title:F.action,due:F.next||qAutoNext(p)||null,from:F.who||'',owner:F.owner,project:p.name,projectId:p.id,client:p.client||'',space:p.space||'',note:((old?.note||'')?old.note+'\n':'')+F.date+' — '+F.text,workUpdate:{text:F.text,date:F.date,at:Date.now(),by:ME.id}};if(old)await j149WriteTask(tid,data);else await j149WriteTask(tid,{...data,kind:'follow',title:F.action,done:false,doneAt:null,status:'waiting',priority:0,createdAt:Date.now(),...(F.owner!==ME.id?{assignedBy:ME.id}:{})},true)}document.getElementById('j149Follow').hidden=true;render();if(cliEdit)drawCli();j149Saved('✓ حُفظت المتابعة وموعدها القادم')}catch(x){error.textContent=(form.dataset.projectSaved?'حُفظ سجل العرض، لكن تعذر تحديث المهمة. أعد الحفظ لإكمالها دون تكرار التواصل. ':'')+(x.message||'تعذر الحفظ')}finally{button.disabled=false}},true);
