quoteView=(f=>function(p){const box=document.createElement('div');box.innerHTML=f.apply(this,arguments);const flow=box.querySelector('.q142');if(flow&&p.status==='quote')flow.insertAdjacentHTML('afterbegin',j149FollowSummary(p));return box.innerHTML})(quoteView);
