function g152Meeting(data,fd){if(data.kind!=='meeting')return data;const mode=String(fd.get('linkMode')||'auto'),project=String(fd.get('project')||'').trim(),client=String(fd.get('client')||'').trim();Object.assign(data,{linkMode:mode,project,client});if(mode==='none'){data.project='';data.client='';delete data.projectId;delete data.clientId;return data}if(mode==='auto'&&!project&&!client){const t=normA(data.title),P=PROJECTS.filter(p=>w146SameSpace(p)&&normA(p.name).length>=5&&t.includes(normA(p.name)));if(P.length===1){data.project=P[0].name;data.projectId=P[0].id;data.client=P[0].client||''}}return w146TaskRefs(data)}
