row=(f=>function(x){const box=document.createElement('div');box.innerHTML=f.apply(this,arguments);if(x.kind==='meeting'){const more=box.querySelector('.more');if(more){const fields=document.createElement('div');fields.className='h152-meeting-fields';fields.innerHTML=`<label>ربط الاجتماع<select data-g152meetingmode="${esc(x.id)}"><option value="auto" ${!x.linkMode||x.linkMode==='auto'?'selected':''}>ربط ذكي قابل للتعديل</option><option value="manual" ${x.linkMode==='manual'?'selected':''}>اختيار المشروع والعميل يدويًا</option><option value="none" ${x.linkMode==='none'?'selected':''}>بدون ارتباط</option></select></label><label>المشروع (اختياري)<input data-f="project" data-id="${esc(x.id)}" list="projList" value="${esc(x.project||'')}" ${x.linkMode==='none'?'disabled':''}></label><label>العميل (اختياري)<input data-f="client" data-id="${esc(x.id)}" list="cliList" value="${esc(x.client||'')}" ${x.linkMode==='none'?'disabled':''}></label>`;more.prepend(fields)}}return box.innerHTML})(row);
