document.addEventListener('change',async e=>{const el=e.target;if(el.matches?.('form.addrow [name=linkMode]')){const f=el.closest('form');for(const name of ['project','client']){const x=f.elements.namedItem(name);x.disabled=el.value==='none';if(x.disabled)x.value=''}return}if(!el.matches?.('[data-g152meetingmode]'))return;e.stopImmediatePropagation();const x=j149Task(el.dataset.g152meetingmode);if(!j149Can(x))return;try{await j149WriteTask(x.id,{linkMode:el.value,...(el.value==='none'?{project:'',client:'',projectId:'',clientId:''}:{})});render()}catch(err){toast(err.message,true)}},true);
