function g152MeetingPending(){return items.filter(x=>x.kind==='meeting'&&x.due&&x.due<today()&&g152After(x.due,1)<=today()&&(!x.meetingResult?.text||tkProj(x)&&!x.meetingResult?.projectLogged)&&(!G152.hidePrivate||!g152Private(x))).sort((a,b)=>b.due.localeCompare(a.due))}
async function g152MeetingResult(id,F){const x=j149Task(id);if(!j149Can(x)||x.kind!=='meeting')throw Error('ليست لديك صلاحية توثيق هذا الاجتماع');const text=String(F.text||'').trim();if(!text)throw Error('اكتب نتيجة الاجتماع أو ما اتُفق عليه');const p=tkProj(x),result={id:x.meetingResult?.id||rid(),date:today(),meetingDate:x.due,at:Date.now(),by:ME.id,text,action:String(F.action||'').trim(),private:g152Private(x)};if(!x.meetingResult?.text)await j149WriteTask(id,{meetingResult:result,note:(x.note?x.note+'\n':'')+today()+' — نتيجة الاجتماع: '+text+(result.action?' — الخطوة التالية: '+result.action:'')});const saved=j149Task(id)?.meetingResult||result;if(p&&!isDemo){const r=await call('recordMeetingOutcome',id);if(r?.event){p.log=[...(p.log||[]).filter(e=>e.meetingId!==id),r.event];p.followEvents=[...(p.followEvents||[]).filter(e=>e.id!==r.event.id),{...r.event,kind:'meeting',text:r.event.subject+' — '+r.event.details}];p.updatedAt=r.updatedAt}await j149WriteTask(id,{meetingResult:{...saved,projectLogged:r?.logged||true}})}else if(p&&pEdit()&&!(x.pv&&p.space!=='p')){await j149SaveProject(p,d=>{if(!(d.log||[]).some(e=>e.id===saved.id)){d.log=[...(d.log||[]),{...saved,kind:'نتيجة اجتماع',subject:x.title,details:'الاجتماع: '+x.due+' — '+saved.text+(saved.action?' — الخطوة التالية: '+saved.action:'')}];d.followEvents=[...(d.followEvents||[]),{...saved,kind:'meeting',text:x.title+' — '+saved.text+(saved.action?' — '+saved.action:'')}]}});await j149WriteTask(id,{meetingResult:{...saved,projectLogged:true}})}if(!p||g152Private(x))await j149WriteTask(id,{meetingResult:{...saved,projectLogged:true}});return saved}
function g152MeetingAlerts(view){if(!['home','day'].includes(tab)||view.querySelector('.h152-meeting-alerts'))return;const rows=g152MeetingPending();if(!rows.length)return;const panel=document.createElement('section');panel.className='panel h152-meeting-alerts';panel.setAttribute('aria-label','تنبيهات نتائج الاجتماعات');panel.innerHTML='<h3>🔔 نتائج اجتماعات تحتاج توثيقًا <small>'+rows.length+'</small></h3><p class="sub">ماذا تم في الاجتماع؟ وثق النتيجة لإضافتها إلى سجل المشروع.</p>'+rows.slice(0,5).map(x=>`<article><div><b>${esc(x.title)}</b><small>${esc(nice(x.due))}${x.project?' · '+esc(x.project):''}${x.client?' · '+esc(x.client):''}</small></div><button class="btn gold xs" type="button" data-g152meetingresult="${esc(x.id)}">تسجيل نتيجة الاجتماع</button></article>`).join('')+(rows.length>5?'<p class="sub">بقية الاجتماعات متاحة من كشف المهام.</p>':'');const anchor=view.querySelector('.h152-privacy,.h150-home-head');anchor?anchor.after(panel):view.prepend(panel)}
