function g152PauseDays(p,until=today()){const ranges=(p.pauses||[]).filter(x=>x.exclude!==false).map(x=>({start:x.start,end:x.end||iso(addDays(parse(until),1))})),days=new Set;for(const r of ranges){if(!f144Date(r.start)||!f144Date(r.end))continue;let d=parse(r.start),n=0;while(iso(d)<r.end&&iso(d)<=until&&n++<15000){if(!holName(d))days.add(iso(d));d=addDays(d,1)}}return days.size}
function g152ActiveDays(p){if(!f144Date(p.start)||p.start>today())return null;let d=parse(p.start),n=0,days=0;while(iso(d)<=today()&&n++<15000){if(!holName(d))days++;d=addDays(d,1)}return Math.max(0,days-g152PauseDays(p))}
function g152PauseChange(p,F,resume){if(!pEdit())throw Error('ليست لديك صلاحية تعديل المشروع');p.pauses=p.pauses||[];const open=p.pauses.find(x=>!x.end);if(resume){if(p.status!=='hold')throw Error('المشروع غير متوقف');if(!String(F.note||'').trim())throw Error('اكتب سبب الاستئناف أو نتيجة مراجعة العميل');if(open){if(today()<open.start)throw Error('تاريخ الاستئناف يسبق التوقف');open.end=today();open.resumeNote=String(F.note).trim();open.resumedBy=ME.id}p.status=open?.resumeStatus||p.resumeStatus||'active';p.log=[...(p.log||[]),{id:rid(),date:today(),kind:'استئناف مشروع',subject:F.mode==='review'?'استئناف لمعالجة ملاحظات العميل':'استئناف المشروع',details:String(F.note).trim()}];delete p.resumeStatus}else{if(open||p.status==='hold')throw Error('المشروع متوقف بالفعل');const reason=String(F.reason||'').trim();if(!reason)throw Error('حدد سبب التوقف');const start=F.start||today();if(!f144Date(start)||start>today()||p.start&&start<p.start)throw Error('راجع بداية التوقف');p.pauses.push({id:rid(),start,end:'',reason,by:ME.id,exclude:true,resumeStatus:p.status});p.resumeStatus=p.status;p.status='hold';p.log=[...(p.log||[]),{id:rid(),date:today(),kind:'إيقاف مشروع',subject:reason,details:String(F.note||'').trim()+' — تستبعد فترة التوقف من مدة العمل الفعلية'}]}return p}
function g152PauseModal(p,resume){modal('g152Pause',`<h2>${resume?'استئناف':'إيقاف'} ${esc(p.name)}</h2><form data-g152pause="${esc(p.id)}" data-resume="${resume?'1':''}">${resume?'<label>الإجراء<select name="mode"><option value="resume">استئناف المشروع</option><option value="review">استئناف لمعالجة ملاحظات العميل</option></select></label>':`<label>سبب التوقف<select name="reason"><option>بانتظار مراجعة العميل</option><option>بانتظار مستندات أو معلومات</option><option>بانتظار اعتماد جهة خارجية</option><option>توقف بطلب العميل</option><option>سبب تعاقدي أو مالي</option><option>سبب آخر موضح أدناه</option></select></label><label>بداية التوقف<input type="date" name="start" value="${today()}" max="${today()}" required></label>`}<label>${resume?'نتيجة الرد / سبب الاستئناف *':'تفاصيل السبب'}<textarea name="note" rows="3" ${resume?'required':''}></textarea></label><p class="sub">تظل تواريخ العقد الأصلية محفوظة. تُعرض أيام التوقف المستبعدة ومدة العمل الفعلية منفصلة، دون تمديد العقد تلقائيًا.</p><div class="auth-err"></div><button class="btn gold">${resume?'تسجيل الاستئناف':'تسجيل التوقف'}</button><button type="button" class="btn ghost" data-mx>إلغاء</button></form>`)}
function g152ScopeOptions(p){const type=ptLabel(p)||'';if(/IFC|تنفيذية/.test(type))return['مراجعة المخططات المعتمدة ومتطلبات الجهات','إعداد المخططات التنفيذية المعمارية','إعداد المخططات التنفيذية الإنشائية','تنسيق مخططات الكهرباء والميكانيكا','معالجة التعارضات بين التخصصات','إصدار حزمة PDF وDWG للمراجعة'];if(/إشراف|ITC/.test(type))return['مراجعة المخططات والمستندات المعتمدة','زيارات إشراف دورية حسب الاتفاق','مراجعة المواد والمخططات المقدمة','توثيق الملاحظات ومتابعة إغلاقها','تقارير الزيارات والتقدم','المشاركة في الاستلام حسب نطاق العقد'];if(/رخص|تراخيص/.test(type))return['مراجعة بيانات الملكية والاشتراطات','تجهيز متطلبات الترخيص','إعداد ورفع المخططات المطلوبة','متابعة ملاحظات الجهة المختصة','استكمال إجراءات إصدار الرخصة'];return['دراسة متطلبات العميل وبيانات الموقع','إعداد الفكرة والتصور الأولي','تطوير التصميم المعماري','تنسيق التخصصات الهندسية','إعداد مستندات المراجعة والاعتماد','تسليم المخططات والملفات المتفق عليها']}
w146OpenHandoff=(f=>function(p){f.apply(this,arguments);const form=document.querySelector('#w146Handoff form');if(!form)return;const draft=p.handoffDraft;if(draft)Object.entries(draft.fields||{}).forEach(([k,v])=>{const el=form.elements.namedItem(k);if(el&&!el.readOnly&&el.type!=='checkbox')el.value=v});const scope=form.elements.scope;if(scope&&!scope.readOnly){scope.insertAdjacentHTML('beforebegin',`<details class="h152-scope"><summary>اختيار بنود نطاق العمل — ${esc(ptLabel(p))}</summary><div>${g152ScopeOptions(p).map((v,i)=>`<button type="button" class="chip" data-g152scope="${i}">${esc(v)}</button>`).join('')}</div><small>اقتراحات قابلة للتعديل؛ أضف فقط ما اتُفق عليه.</small></details>`)}form.querySelector('.row2')?.insertAdjacentHTML('afterbegin','<button type="button" class="btn ghost" data-g152draft>حفظ مسودة واستكمال لاحقًا</button>')})(w146OpenHandoff);
