function i155Rows(){const d=today(),uid=ME?.id;return items.filter(x=>!g152Private(x)||PRIV()).filter(x=>PRIV()?x.owner===uid:x.space!=='p').filter(x=>x.owner===uid||x.assignedBy===uid||x.wf?.req?.ap===uid).flatMap(x=>{const r=[];if(x.wf?.req?.ap===uid)r.push({id:x.id+':approval',x,label:'طلب يحتاج اعتمادك'});if(x.kind==='meeting'&&x.due&&x.due<d&&!x.meetingResult?.text)r.push({id:x.id+':outcome',x,label:'نتيجة اجتماع تحتاج توثيقًا'});else if(!x.done&&x.due&&x.due<=d)r.push({id:x.id+':'+x.due,x,label:x.kind==='follow'?'متابعة مستحقة':x.kind==='meeting'?'اجتماع اليوم':x.due<d?'مهمة متأخرة':'مهمة مستحقة اليوم'});return r}).sort((a,b)=>String(a.x.due||'').localeCompare(String(b.x.due||'')))}
function i155Center(){const L=i155Rows();modal('i155Center',`<h2>🔔 مركز التنبيهات <small>${L.length}</small></h2><p class="sub">${PRIV()?'تنبيهات أعمالك الخاصة':'التنبيهات العامة تستبعد الأعمال الخاصة'}. يختفي التنبيه بعد إتمام الإجراء المطلوب.</p><div class="i155-notices">${L.map(r=>`<button class="i155-notice" data-i155open="${esc(r.x.id)}"><small>${esc(r.label)} · ${esc(r.x.due||'')}</small><b>${esc(r.x.title)}</b><span>${esc([r.x.project,r.x.client].filter(Boolean).join(' · '))}</span></button>`).join('')||'<p>لا توجد إجراءات مستحقة الآن.</p>'}</div><button class="btn ghost" type="button" data-mx>إغلاق</button>`)}
async function i155Load(){if(I155.busy||isDemo||!ME)return;I155.busy=true;try{I155.data=await api('integrationStatus155');I155.error='';I155.at=Date.now()}catch(e){I155.error=e.message}finally{I155.busy=false;if(['health','todo','users'].includes(tab))render()}}
function i155Panel(){if(!I155.at&&!I155.busy)setTimeout(i155Load,0);const d=I155.data,r=d?.remote;return `<section class="panel i155-panel"><h3>🔗 حالة الربط والتنبيهات <button class="btn ghost xs" data-i155refresh>تحديث الفحص</button></h3>${I155.error?`<p class="i155-error">${esc(I155.error)}</p>`:''}<div class="i155-grid"><div><small>اتصال خدمات Google</small><b>${!d?'جارٍ الفحص…':d.needsLogin?'يحتاج تجديد الاتصال':d.error?'تعذر التحقق':r?'متصل':'يحتاج تحديث خدمة الربط'}</b></div><div><small>تعديلات تنتظر المزامنة</small><b>${d?num(d.pending):'—'}</b></div><div><small>Microsoft To Do</small><b>${r?(r.todo?.on?(r.todo.rw?'مربوط — قراءة وكتابة':'مربوط — قراءة فقط'):'غير مربوط'):'لم يُتحقق منه'}</b></div><div><small>جدولة الملخص والتذكيرات</small><b>${r?(r.daily&&r.reminder?'مفعّلة':'تحتاج إصلاح الجدولة'):'لم يُتحقق منها'}</b></div></div>${d?.error?`<p class="sub">${esc(d.error)}</p>`:''}<p class="sub">التنبيهات داخل الصفحة مستقلة عن البريد. قبول خدمة البريد للرسالة لا يؤكد وصولها للبريد الوارد.</p><div class="i155-actions">${d?.needsLogin?'<button class="btn gold" data-i155reconnect>تجديد اتصال حساب يومي</button>':''}<button class="btn ghost" data-i155retry>إعادة محاولة المزامنة</button>${r?'<button class="btn ghost" data-i155digest>إرسال ملخصي الآن</button>':''}${r&&!r.daily&&d.manager?'<button class="btn ghost" data-i155schedule>إصلاح جدولة التنبيهات</button>':''}</div>${d?.failures?.length?`<details><summary>تعديلات لم تكتمل مزامنتها (${d.failures.length})</summary>${d.failures.map(x=>`<p>${esc(x.fn)} — ${esc(x.error||'بانتظار المحاولة')}</p>`).join('')}</details>`:''}${r?.delivery?.length?`<details><summary>آخر محاولات إرسال بريدي</summary>${r.delivery.map(x=>`<p>${esc(x.at)} · ${x.ok?'قُبل الإرسال':'تعذر الإرسال'} · ${esc(x.kind||'بريد')}</p>`).join('')}</details>`:''}</section>`}
render=(f=>function(){const r=f.apply(this,arguments);if(ME&&['health','todo','users'].includes(tab)){const v=document.getElementById('view');if(v&&!v.querySelector('.i155-panel'))v.insertAdjacentHTML('afterbegin',i155Panel())}if(ME){let b=document.getElementById('i155Bell');if(!b){b=document.createElement('button');b.id='i155Bell';b.className='btn ghost xs';b.type='button';document.getElementById('helpBtn')?.insertAdjacentElement('afterend',b)}b.textContent='🔔 '+i155Rows().length;b.setAttribute('aria-label','مركز التنبيهات')}document.querySelectorAll('[data-pralert]').forEach(b=>{if(b.textContent.includes('التنبيهات مفعّلة'))b.textContent='🔔 تنبيهات الصلاة مفعّلة'});return r})(render);
document.addEventListener('click',e=>{const b=e.target.closest?.('#i155Bell,[data-i155open]');if(!b)return;e.preventDefault();if(b.id==='i155Bell')i155Center();else{document.getElementById('i155Center').hidden=true;goItem(b.dataset.i155open)}},true);
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-i155refresh],[data-i155reconnect],[data-i155retry],[data-i155digest],[data-i155schedule]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-i155reconnect')){modal('i155Reconnect',`<h2>تجديد اتصال خدمات يومي</h2><p class="sub">أدخل كلمة مرور حساب يومي الحالي. لا تحتاج تغيير كلمة المرور أو فصل Microsoft To Do.</p><form data-i155form><label>كلمة مرور يومي<input type="password" name="password" autocomplete="current-password" required maxlength="256"></label><p class="auth-err"></p><button class="btn gold">تجديد الاتصال</button><button class="btn ghost" type="button" data-mx>إلغاء</button></form>`);return}b.disabled=true;try{if(b.hasAttribute('data-i155retry')){await api('retryIntegrations155');toast('انتهت محاولة المزامنة؛ راجع نتيجة الفحص')}else if(b.hasAttribute('data-i155digest')){const r=await api('sendDigest');toast('قُبل إرسال الملخص إلى '+r.to)}else if(b.hasAttribute('data-i155schedule')){await api('repairNotifications155');toast('حُدثت جدولة التنبيهات')}await i155Load()}catch(x){toast(x.message,true)}finally{b.disabled=false}},true);
document.addEventListener('submit',async e=>{const f=e.target.closest?.('[data-i155form]');if(!f)return;e.preventDefault();e.stopImmediatePropagation();const b=f.querySelector('button');b.disabled=true;try{await api('reconnect155',f.elements.password.value);f.elements.password.value='';document.getElementById('i155Reconnect').hidden=true;toast('تم تجديد الاتصال');await api('retryIntegrations155');await i155Load();if(tab==='todo'){try{TODO=await api('todoStatus')}catch{}render()}}catch(x){f.querySelector('.auth-err').textContent=x.message;f.elements.password.value='';b.disabled=false}},true);

// v156: preserve the established identity and action order; improve hierarchy.
var V156={folds:{}};
function v156Decorate(){const v=document.getElementById('view');if(!v)return;v.dataset.page=tab;
 if(['users','health'].includes(tab)){const panel=v.querySelector('.i155-panel');if(panel&&!panel.closest('.v156-integration')){const d=document.createElement('details');d.className='v156-integration';d.dataset.v156fold=tab;d.open=V156.folds[tab]??!!I155.data?.needsLogin;const summary=document.createElement('summary');summary.textContent='🔗 حالة الربط والتنبيهات — '+(I155.data?.needsLogin?'تحتاج متابعة':I155.data?.remote?'متصل':'عرض الفحص');panel.replaceWith(d);d.append(summary,panel)}}
 if(tab==='users')v.querySelectorAll('.tblwrap').forEach(box=>{const table=box.querySelector('table');if(!table)return;box.classList.add('v156-permissions');box.setAttribute('tabindex','0');box.setAttribute('role','region');box.setAttribute('aria-label','جدول المستخدمين والصلاحيات؛ يمكن التمرير أفقيًا');if(!box.previousElementSibling?.classList.contains('v156-tablehint')){const hint=document.createElement('p');hint.className='v156-tablehint sub';hint.textContent='↔ اسحب الجدول لعرض بقية الصلاحيات؛ اسم المستخدم ثابت أثناء التمرير.';box.before(hint)}table.querySelectorAll('tbody tr').forEach(row=>row.querySelectorAll('input[type=checkbox]').forEach(input=>{if(input.hasAttribute('aria-label'))return;const cell=input.closest('td'),head=table.querySelectorAll('thead th')[cell?.cellIndex];input.setAttribute('aria-label',(head?.textContent.trim()||'الصلاحية')+' — '+(row.cells[0]?.textContent.trim().slice(0,100)||'المستخدم'))}))});
}
render=(f=>function(){const r=f.apply(this,arguments);v156Decorate();return r})(render);
document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-v156fold]'))V156.folds[e.target.dataset.v156fold]=e.target.open},true);

