async function createCompanyUser158(form){const fd=new FormData(form),g=k=>String(fd.get(k)||'').trim(),profile=COMPANY158.find(x=>x[0]===g('companyProfile158')),button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;let created=false;try{const username=g('username').toLowerCase();USERS=await api('addUser',username,g('name'),g('role'),String(fd.get('password')||''),{branch:g('branch'),dept:g('dept'),title:g('title')},g('email'));created=true;const user=USERS.find(x=>x.username===username);if(profile?.[3]&&profile[2]===g('role')){if(!user)throw Error('أُنشئ الحساب؛ لم يتوفر معرّفه لتطبيق النموذج');USERS=await api('updateUser',user.id,{perms:profile[3]})}setChip();render();toast('✓ أُضيف المستخدم'+(profile?' وطُبق النموذج الوظيفي':''))}catch(e){if(created){setChip();render();banner('أُنشئ الحساب بالفعل. تعذر إكمال نموذج الصلاحيات؛ راجع صف المستخدم قبل إسناد العمل له. لا تعِد إنشاءه. '+(e.message||''),true)}else banner(e.message||'تعذرت إضافة المستخدم',true)}finally{if(button)button.disabled=false}}


