function e163Allowed(route){const button=document.querySelector(`nav.tabs [data-tab="${route}"]`);return !!button&&!button.hidden}
function e163Route(route,label,cls=''){return e163Allowed(route)?`<button type="button" class="${cls}" data-h162-go="${route}">${label}</button>`:''}
function e163Task(x){return `<button type="button" class="e163-task" data-h162-task="${esc(x.id)}"><span class="e163-task-dot" aria-hidden="true"></span><span><b>${esc(x.title)}</b><small>${esc(x.project||'دون مشروع')} · ${esc(uname(x.owner)||'غير مسندة')}</small></span><span class="e163-due ${x.due<today()?'late':''}">${x.due?esc(nice(x.due)):'دون موعد'}</span></button>`}
function e163Home(){
 if(!ME)return '';
 const now=today(),tasks=items.filter(x=>!x.pv&&!['meeting','note','idea'].includes(x.kind)),open=tasks.filter(x=>!x.done),late=open.filter(x=>x.due&&x.due<now),due=open.filter(x=>x.due&&x.due<=now).sort((a,b)=>String(a.due).localeCompare(String(b.due))),projects=(PRIV()||can('projects'))?PV():[],active=projects.filter(p=>p.status==='active');
 const decisions=e163Allowed('approvals')?ALLI().filter(x=>!x.pv&&wfReq(x)&&wfReq(x).by!==ME.id&&canAp(x)):[];
 const completed=tasks.filter(x=>x.done&&x.doneAt&&h162Date(x.doneAt)!=='غير مؤرخ').sort((a,b)=>new Date(b.doneAt)-new Date(a.doneAt)).slice(0,3),dateText=new Intl.DateTimeFormat('ar-EG',{dateStyle:'full',timeZone:'Asia/Riyadh'}).format(new Date());
 const scopeName=typeof TEN!=='undefined'&&TEN?(TEN.name||TEN.title||'مساحة العمل'):'مساحة العمل';
 return `<div class="e163"><header class="e163-welcome"><div><span class="e163-eyebrow">${esc(scopeName)} / المتابعة التنفيذية</span><h1>قرارات أوضح.<br>وأعمال تتقدم.</h1><p>${esc(dateText)} · ملخص ما هو متاح لك في العرض الحالي.</p></div>${e163Route('approvals','مراجعة طلبات الاعتماد ←','e163-primary')}</header>
 <div class="e163-kpis"><section class="e163-kpi featured"><span>طلبات بانتظار قرارك</span><strong>${decisions.length}</strong><small>طلبات سير العمل التي تملك صلاحية اعتمادها</small>${e163Route('approvals','عرض الطلبات')}</section><section class="e163-kpi"><span>مشاريع قيد العمل</span><strong>${active.length}</strong><small>من المشاريع المتاحة لك</small>${e163Route('projects','عرض المشاريع')}</section><section class="e163-kpi"><span>مهام متأخرة</span><strong>${late.length}</strong><small>تجاوزت موعدها ولم تكتمل في العرض الحالي</small>${e163Route('day','متابعة المهام')}</section></div>
 <div class="e163-grid"><section class="e163-panel"><header><div><h2>أولويات المتابعة</h2><p>المستحق حتى اليوم، مرتب حسب الموعد.</p></div>${e163Route('day','عرض الكل')}</header><div>${due.slice(0,4).map(e163Task).join('')||'<p class="e163-empty">لا توجد مهام مستحقة أو متأخرة في العرض الحالي.</p>'}</div></section>
 <section class="e163-panel"><header><div><h2>مشاريع تحت المتابعة</h2><p>مصدر النسبة موضّح لكل مشروع.</p></div>${e163Route('projects','عرض الكل')}</header><div class="e163-projects">${active.slice(0,4).map(p=>{const progress=h162ProjectProgress(p);return `<button type="button" data-h162-project="${esc(p.id)}"><span><b>${esc(p.name)}</b><small>${esc(p.client||'')}</small></span><strong>${progress.value===null?'—':progress.value+'%'}</strong><progress max="100" value="${progress.value??0}" aria-label="${esc(p.name)}: ${esc(progress.source)}"></progress><small class="e163-progress-source">${esc(progress.source)}</small></button>`}).join('')||'<p class="e163-empty">لا توجد مشاريع قيد العمل.</p>'}</div></section>
 <section class="e163-panel"><header><div><h2>طلبات الاعتماد</h2><p>راجع تفاصيل الطلب في مسار الموافقات الأصلي.</p></div>${e163Route('approvals','كل الطلبات')}</header>${decisions.slice(0,3).map(x=>`<button type="button" class="e163-decision" data-h162-go="approvals"><span>${h162Icon('document')}</span><span><b>${esc(x.title)}</b><small>${esc(WFT[wfReq(x).type]||'طلب إجراء')} · ${esc(uname(wfReq(x).by)||'')}</small></span><span>مراجعة ←</span></button>`).join('')||'<p class="e163-empty">لا توجد طلبات تحتاج قرارك حاليًا.</p>'}</section>
 <section class="e163-panel"><header><div><h2>آخر المهام المكتملة</h2><p>سجل الإنجاز حسب تواريخ الإكمال المسجلة.</p></div>${e163Route('done','سجل الإنجاز')}</header><div class="e163-completed">${completed.map(x=>`<div><span class="e163-complete-dot"></span><div><b>${esc(x.title)}</b><small>${esc(x.project||'دون مشروع')}</small></div><time>${esc(h162Date(x.doneAt))}</time></div>`).join('')||'<p class="e163-empty">ستظهر المهام بعد تسجيل اكتمالها.</p>'}</div></section></div>
 <footer class="e163-footer"><span>كل رقم مرتبط بنطاق البيانات والصلاحيات الحالية.</span><button type="button" data-h162-appearance>الواجهة والشعار والخط</button>${e163Route('home','العودة للرئيسية')}</footer></div>`;
}
