function g164View(){
 const projects=(PRIV()||can('projects'))?PV():[];const p=projects.find(x=>x.id===g164Selected)||projects.find(x=>x.status==='active')||projects[0];
 if(!p)return `<div class="g164"><section class="g164-empty"><h1>مساحة المشاريع الهندسية</h1><p>لا توجد مشاريع متاحة في مساحة العمل الحالية.</p>${pEdit()?'<button class="btn gold" data-pnew>+ مشروع جديد</button>':''}</section></div>`;
 g164Selected=p.id;const safe=g164Clone(p),progress=h162ProjectProgress(safe),steps=(p.steps||[]).filter(x=>x.name),nextStep=steps.findIndex(x=>!x.done),tasks=items.filter(x=>!x.pv&&x.project===p.name&&!['meeting','note','idea'].includes(x.kind)),pending=tasks.filter(x=>!x.done),docs=(p.docs||[]).slice().sort((a,b)=>(new Date(b.at).getTime()||0)-(new Date(a.at).getTime()||0)),shown=g164DocFilter==='all'?docs:docs.filter(d=>(d.cat||'غير مصنّف')===g164DocFilter),cats=[...new Set(docs.map(d=>d.cat||'غير مصنّف'))],status=PSTL[p.status]?.l||p.status||'غير محدد',next=w146Next(safe);
 return `<div class="g164"><div class="g164-selector"><label for="g164-project">المشروع الحالي</label><select id="g164-project">${projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span>${projects.length} مشاريع متاحة</span></div>
 <section class="g164-project-head"><div class="g164-title"><span class="g164-icon">${h162Icon('project')}</span><div><span class="g164-eyebrow">مساحة المشاريع الهندسية</span><h1>${esc(p.name)}</h1><p>${esc(p.loc||'الموقع غير مسجل')}</p></div></div><dl><div><dt>حالة المشروع</dt><dd>${esc(status)}</dd></div><div><dt>العميل</dt><dd>${esc(p.client||'غير محدد')}</dd></div><div><dt>المسؤول</dt><dd>${esc(next.owner||'غير محدد')}</dd></div></dl><button type="button" class="g164-primary" data-h162-project="${esc(p.id)}">فتح ملف المشروع ←</button></section>
 <section class="g164-stages"><header><div><h2>المراحل والخطوات الفنية</h2><p>الخطوات المسجلة للمشروع، مستقلة عن مراحل الدفعات.</p></div><span>${steps.filter(s=>s.done).length} / ${steps.length} مكتملة</span></header>${steps.length?`<ol>${steps.slice(0,8).map((s,i)=>`<li class="${s.done?'done':i===nextStep?'next':''}"><span class="g164-step-num">${s.done?'✓':i+1}</span><b>${esc(s.name)}</b><time>${g164Date(s.due)}</time><small>${s.done?'مكتملة':i===nextStep?'التالي للمتابعة':'لم تكتمل'}</small></li>`).join('')}</ol>${steps.length>8?'<p class="g164-caption">تظهر أول 8 خطوات؛ بقية الخطوات في ملف المشروع.</p>':''}`:`<div class="g164-stage-empty"><span>${h162Icon('project')}</span><div><b>لم تُسجّل خطوات فنية لهذا المشروع</b><p>سجّل المراحل والمخرجات من ملف المشروع لعرض تقدم فني قابل للمتابعة.</p></div><button type="button" data-h162-project="${esc(p.id)}" data-h162-section="steps">عرض الخطوات</button></div>`}</section>
 <div class="g164-workspace"><aside class="g164-summary"><h2>ملخص المشروع</h2><div class="g164-progress-ring" style="--g-progress:${progress.value??0}%"><strong>${progress.value===null?'—':progress.value+'%'}</strong></div><p class="g164-progress-source">${esc(progress.source)}</p><dl><div><dt>تاريخ البدء</dt><dd>${g164Date(p.start)}</dd></div><div><dt>الانتهاء المتوقع</dt><dd>${g164Date(p.end)}</dd></div><div><dt>المستندات المرفقة</dt><dd>${docs.length}</dd></div><div><dt>المهام المفتوحة في العرض الحالي</dt><dd>${pending.length}</dd></div></dl><div class="g164-next"><small>المطلوب التالي</small><b>${esc(next.title||'راجع خطة المشروع')}</b>${next.due?`<time>${esc(g164Date(next.due))}</time>`:''}</div></aside>
 <section class="g164-documents"><header><div><h2>المخططات ومستندات المشروع</h2><p>المرفقات الفعلية المتاحة في ملف المشروع.</p></div><button type="button" data-h162-project="${esc(p.id)}" data-h162-section="docs">فتح المستندات</button></header><div class="g164-filters"><button type="button" data-g164-cat="all" aria-pressed="${g164DocFilter==='all'}">الكل (${docs.length})</button>${cats.map(c=>`<button type="button" data-g164-cat="${esc(c)}" aria-pressed="${g164DocFilter===c}">${esc(c)}</button>`).join('')}</div>${shown.length?`<div class="g164-table-wrap"><table><thead><tr><th>#</th><th>اسم المستند</th><th>التصنيف</th><th>تاريخ الإضافة</th><th>الإجراء</th></tr></thead><tbody>${shown.map((d,i)=>`<tr><td>${i+1}</td><td><span class="g164-file-icon">${h162Icon('document')}</span><b>${esc(d.name||'مستند دون اسم')}</b></td><td>${esc(d.cat||'غير مصنّف')}</td><td>${g164Date(d.at)}</td><td><button type="button" data-h162-project="${esc(p.id)}" data-h162-section="docs">عرض الملف</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="g164-empty"><span class="g164-file-icon">'+h162Icon('document')+'</span><h3>لا توجد مستندات مطابقة</h3><p>ارفع المخططات والمرفقات من ملف المشروع لتظهر هنا.</p></div>'}<div class="g164-deliverables"><h3>تكليفات المشروع في العرض الحالي</h3>${pending.slice(0,4).map(e163Task).join('')||'<p class="g164-caption">لا توجد تكليفات مفتوحة ضمن العرض الحالي.</p>'}</div></section></div><footer class="g164-footer"><span>لا يدل إرفاق مستند على مراجعته أو اعتماده.</span><button type="button" data-h162-appearance>تخصيص الواجهة والشعار والخط</button></footer></div>`;
}
