let b165Project='',b165Query='',b165Native=false,f165Selected='';
function b165View(){
 const tasks=items.filter(x=>!x.pv&&!['meeting','note','idea'].includes(x.kind)),names=[...new Set(tasks.map(x=>x.project).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar')),query=normA(b165Query),filtered=tasks.filter(x=>(!b165Project||x.project===b165Project)&&(!query||normA([x.title,x.project,uname(x.owner)].join(' ')).includes(query)));
 return `<div class="b165"><header class="b165-head"><div><span class="w165-eyebrow">مساحة العمل / لوحة المهام</span><h1>كل مهمة في مكانها.</h1><p>الحالات المسجلة للمهام المتاحة في العرض الحالي.</p></div><div class="w165-actions"><button type="button" data-w165-add>+ إضافة جديد</button><button type="button" data-b165-native>الكشف والتصدير</button></div></header><form class="b165-filters" id="b165-filter"><label>المشروع<select name="project"><option value="">كل المشاريع</option>${names.map(n=>`<option value="${esc(n)}" ${n===b165Project?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>البحث<input name="query" value="${esc(b165Query)}" placeholder="عنوان المهمة أو المشروع أو المسؤول"></label><button type="submit">تطبيق</button><button type="button" data-b165-reset>مسح التصفية</button><span>${filtered.length} مهمة</span></form>
 <div class="b165-board">${KBC.map(([key,label])=>{const lane=filtered.filter(x=>kbCol({x,s:taskState(x)})===key);return `<section class="b165-lane ${key}" data-b165-lane="${key}" aria-label="${label}"><header><h2>${label}</h2><b>${lane.length}</b></header><div>${lane.map(x=>`<article class="b165-card" ${j149Can(x)&&!x.done?'draggable="true"':''} data-b165-task="${esc(x.id)}"><small class="b165-project">${esc(x.project||'دون مشروع')}</small><h3><button type="button" data-h162-task="${esc(x.id)}">${esc(x.title)}</button></h3>${wfReq(x)?wfPill(x):''}<footer><time class="${!x.done&&x.due&&x.due<today()?'late':''}">${x.due?esc(nice(x.due)):'دون موعد'}</time><span class="b165-owner" title="${esc(uname(x.owner)||'غير محدد')}">${esc(String(uname(x.owner)||'؟').slice(0,1))}</span></footer><button class="b165-update" type="button" data-h162-task="${esc(x.id)}">${j149Can(x)?'تسجيل تقدم / تحديث الحالة':'عرض حسب الصلاحية'}</button></article>`).join('')||'<p class="b165-empty">لا توجد مهام في هذه الحالة.</p>'}</div></section>`}).join('')}</div><footer class="w165-footer">اسحب المهمة إلى عمود لفتح نموذج تحديثها، أو استخدم زر التحديث. تُطبّق الحالة بعد تسجيل المستجد وحفظه وفق الصلاحيات.<button type="button" data-h162-appearance>الواجهة والشعار والخط</button></footer></div>`;
}
function f165View(){
 const now=today(),tasks=items.filter(x=>!x.pv&&!['meeting','note','idea'].includes(x.kind)&&!x.done).sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999'))),due=tasks.filter(x=>x.due&&x.due<=now),selected=tasks.find(x=>x.id===f165Selected)||due[0]||tasks[0],meetings=items.filter(x=>!x.pv&&x.kind==='meeting'&&x.due===now).sort((a,b)=>String(a.time||'').localeCompare(String(b.time||''))),done=items.filter(x=>!x.pv&&x.done&&x.doneAt&&h162Date(x.doneAt)===now).length;
 return `<div class="f165"><header class="f165-welcome"><span class="w165-eyebrow">مساحة التركيز الشخصي</span><h1>أهلاً، ${esc(String(ME?.name||'').split(' ')[0])}.</h1><p>خطوة واضحة، ثم التي تليها.</p></header><div class="f165-layout"><div><section class="f165-priority"><div><span class="w165-eyebrow">${selected?'خطوتك التالية المقترحة':'مساحة ليوم أخف'}</span><h2>${selected?esc(selected.title):'لا توجد مهام مفتوحة.'}</h2><p>${selected?esc(selected.project||'دون مشروع')+' · '+esc(uname(selected.owner)||'غير محدد'):'راجع إنجازك أو أضف مهمة جديدة.'}</p>${selected?.deliverable?`<p class="f165-deliverable">المخرج المطلوب: ${esc(selected.deliverable)}</p>`:''}${selected?`<button type="button" class="f165-primary" data-h162-task="${esc(selected.id)}">افتح المهمة وسجّل تقدمك ←</button>`:'<button type="button" class="f165-primary" data-w165-add>+ إضافة جديد</button>'}</div></section><section class="f165-tasks"><header><h2>المهام المستحقة</h2><span>${due.length} مهام</span></header>${due.slice(0,6).map(x=>`<div class="f165-task"><button class="f165-pick" type="button" data-f165-pick="${esc(x.id)}" aria-label="التركيز على ${esc(x.title)}" aria-pressed="${selected?.id===x.id}">◎</button><button type="button" data-h162-task="${esc(x.id)}"><b>${esc(x.title)}</b><small>${esc(x.project||'دون مشروع')} · ${x.due<now?'متأخرة': 'اليوم'}</small></button></div>`).join('')||'<p class="w165-empty">لا توجد مهام مستحقة حتى اليوم.</p>'}<button class="f165-all" type="button" data-h162-go="day">عرض صفحة اليوم ←</button></section></div><aside class="f165-agenda"><header><h2>اجتماعات اليوم</h2>${e163Route('meetings','عرض الكل')}</header>${meetings.slice(0,6).map(m=>`<button type="button" data-h162-go="meetings"><time>${esc(m.time||'غير محدد')}</time><b>${esc(m.title)}</b><small>${esc(m.project||'اجتماع عام')}</small></button>`).join('')||'<p class="w165-empty">لا توجد اجتماعات مسجلة اليوم.</p>'}<div class="f165-achievement"><strong>${done}</strong><span>مهام اكتملت اليوم في العرض الحالي</span></div><p class="f165-note">اقتراح الأولوية حسب الموعد. يمكنك اختيار مهمة للتركيز عليها من القائمة.</p></aside></div><footer class="w165-footer"><span>صور المكتب توضيحية وليست مخططات مشروع فعلي.</span><button type="button" data-h162-appearance>الواجهة والشعار والخط</button></footer></div>`;
}
