let t166Date=today();
function t166TaskTable(tasks){return tasks.length?`<div class="t166-table"><table><thead><tr><th>المهمة</th><th>المشروع</th><th>المسؤول</th><th>الموعد</th><th>الحالة</th></tr></thead><tbody>${tasks.map(x=>`<tr><td><button type="button" data-h162-task="${esc(x.id)}">${esc(x.title)}</button></td><td>${esc(x.project||'—')}</td><td>${esc(uname(x.owner)||'—')}</td><td>${x.due?esc(nice(x.due)):'دون موعد'}</td><td>${esc(ASTL[taskState(x)]?.l||'غير محددة')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="t166-empty">لا توجد مهام مطابقة في العرض الحالي.</p>'}
