 if(id==='calendar'){const date=parse(t166Date),first=new Date(date.getFullYear(),date.getMonth(),1),last=new Date(date.getFullYear(),date.getMonth()+1,0),offset=first.getDay(),days=last.getDate();body=`<div class="t166-calendar-layout"><section class="t166-panel"><header class="t166-month-head"><button type="button" data-t166-month="-1" aria-label="الشهر السابق">‹</button><h2>${new Intl.DateTimeFormat('ar-EG',{month:'long',year:'numeric'}).format(date)}</h2><button type="button" data-t166-month="1" aria-label="الشهر التالي">›</button></header><div class="t166-month">${['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'].map(d=>`<small>${d}</small>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const d=iso(new Date(date.getFullYear(),date.getMonth(),i+1)),count=tasks.filter(x=>x.due===d).length;return `<button type="button" data-t166-date="${d}" aria-pressed="${d===t166Date}"><b>${i+1}</b>${count?`<small>${count} مهام</small>`:''}</button>`}).join('')}</div></section>${t166Panel('مهام '+esc(nice(t166Date)),t166Tasks(tasks.filter(x=>x.due===t166Date)))}</div>`;}
