 if(id==='grouped'){const names=[...new Set(open.map(x=>x.project||'دون مشروع'))];body=`<div class="t166-groups">${names.map(n=>`<details open><summary>${esc(n)} <span>${open.filter(x=>(x.project||'دون مشروع')===n).length} مهام</span></summary>${t166Tasks(open.filter(x=>(x.project||'دون مشروع')===n))}</details>`).join('')||'<p class="t166-empty">لا توجد تكليفات مفتوحة.</p>'}</div>`;}
