function a170Icon(n){const P={folder:'<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',check:'<path d="m5 12 4 4L19 6"/>',cal:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18"/>',doc:'<path d="M6 3h8l5 5v13H6Z"/><path d="M14 3v5h5M9 13h7M9 17h5"/>',dots:'<circle cx="12" cy="5" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="12" cy="19" r="1.4"/>',dl:'<path d="M12 4v11m-5-5 5 5 5-5M5 20h14"/>',pin:'<path d="M12 21s7-6 7-12a7 7 0 0 0-14 0c0 6 7 12 7 12Z"/><circle cx="12" cy="9" r="2.5"/>',send:'<path d="M4 12 20 4l-6 16-3-7Z"/>',spark:'<path d="M12 3v4M12 17v4M3 12h4M17 12h4M6 6l2.5 2.5M15.5 15.5 18 18M6 18l2.5-2.5M15.5 8.5 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chev:'<path d="m15 6-6 6 6 6"/>',chevl:'<path d="m9 6 6 6-6 6"/>',edit:'<path d="M4 20h4L19 9l-4-4L4 16Z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20a6 6 0 0 1 12 0M16 5a3 3 0 0 1 0 6M18 20a6 6 0 0 0-3-5"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',teams:'<rect x="3" y="6" width="12" height="12" rx="2"/><path d="M7 10h4M9 10v5M17 9h3v6a3 3 0 0 1-3 3"/>',grid:'<rect x="4" y="4" width="7" height="7" rx="1.5"/><rect x="13" y="4" width="7" height="7" rx="1.5"/><rect x="4" y="13" width="7" height="7" rx="1.5"/><rect x="13" y="13" width="7" height="7" rx="1.5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${P[n]||P.doc}</svg>`}
function a170Head(title,route,extra=''){return `<header class="a170-head"><h2>${title}</h2><div>${extra}${route?`<button type="button" class="a170-link" data-a170-go="${route}">عرض الكل ‹</button>`:''}</div></header>`}
function a170ProjImg(p){for(const d of Array.isArray(p.docs)?p.docs:[]){const u=String(d.url||d.link||'');if(/^https?:\/\/.+\.(png|jpe?g|webp)(\?|$)/i.test(u))return {src:u,real:true}}return {src:'assets/hybrid/project.jpg',real:false}}
function a170Pct(p){try{return h162ProjectProgress(p).value}catch{return null}}
function a170Greeting(){const h=Number(a170Fmt({hour:'2-digit',hour12:false}));return h<12?'صباح الخير':'مساء الخير'}
function a170Prayer(){try{const s=prState(),m=Math.max(0,Math.round((s.nt-new Date)/6e4));return `<button type="button" class="a170-prayer" data-a170-prayer>${a170Icon('moon')}<span>الصلاة القادمة <b>${PRN[s.nx]||''} ${s.nt.toLocaleTimeString('ar-EG-u-nu-latn',{hour:'2-digit',minute:'2-digit'})}</b> · بعد ${m>=60?Math.floor(m/60)+' س ':''}${m%60} د</span></button>`}catch{return ''}}
const A170_WCODE={0:'صافٍ',1:'صافٍ غالباً',2:'غائم جزئياً',3:'غائم',45:'ضباب',48:'ضباب',51:'رذاذ',61:'مطر خفيف',63:'مطر',65:'مطر غزير',80:'زخات',95:'عاصفة رعدية'};
let a170WeatherFail=0;function a170LoadWeather(){if(a170Weather||a170WeatherBusy||Date.now()-a170WeatherFail<600000)return;try{const c=JSON.parse(localStorage.getItem('yawmi:a170:weather')||'null');if(c&&Date.now()-c.at<1800000){a170Weather=c;return}}catch{}a170WeatherBusy=true;fetch('https://api.open-meteo.com/v1/forecast?latitude=21.4225&longitude=39.8262&current=temperature_2m,weather_code&daily=temperature_2m_max,temperature_2m_min&timezone=Asia%2FRiyadh&forecast_days=1').then(r=>r.json()).then(j=>{a170Weather={at:Date.now(),t:Math.round(j.current.temperature_2m),c:j.current.weather_code,hi:Math.round(j.daily.temperature_2m_max[0]),lo:Math.round(j.daily.temperature_2m_min[0])};try{localStorage.setItem('yawmi:a170:weather',JSON.stringify(a170Weather))}catch{}const w=document.querySelector('.a170-weather');if(w)w.outerHTML=a170WeatherHtml()}).catch(()=>{a170WeatherFail=Date.now()}).finally(()=>{a170WeatherBusy=false})}
function a170WeatherHtml(){const w=a170Weather;return `<div class="a170-weather"><small>مكة المكرمة</small><span>${a170Icon('sun')}<b>${w?w.t+'°C':'—'}</b></span><small>${w?(A170_WCODE[w.c]||'')+' · العظمى '+w.hi+'° الصغرى '+w.lo+'°':'الطقس غير متاح الآن'}</small></div>`}
function a170Data(){const t=today(),scoped=items.filter(x=>!x.pv&&!['note','idea'].includes(x.kind)),tasks=scoped.filter(x=>x.kind!=='meeting'),meetings=scoped.filter(x=>x.kind==='meeting'),todayTasks=tasks.filter(x=>x.due===t||(!x.done&&x.due&&x.due<t)),projects=(PRIV()||can('projects'))?PV():[],active=projects.filter(p=>p.status==='active'),todayMeet=meetings.filter(x=>x.due===t).sort((a,b)=>String(a.time||'').localeCompare(String(b.time||''))),docs=projects.flatMap(p=>(p.docs||[]).map(d=>({p,d}))).sort((a,b)=>(b.d.at||0)-(a.d.at||0)),weekAgo=Date.now()-7*864e5;return {t,tasks,meetings,todayTasks,projects,active,todayMeet,docs,newDocs:docs.filter(x=>(x.d.at||0)>=weekAgo),done:tasks.filter(x=>x.done)}}
function a170Hero(D){const first=String(ME.name||'').split(' ')[0],openToday=D.todayTasks.filter(x=>!x.done),featured=[...D.active].sort((a,b)=>(a170Pct(b)??-1)-(a170Pct(a)??-1))[0]||D.projects[0],todayDone=D.todayTasks.filter(x=>x.done).length,img=featured?a170ProjImg(featured):null,fp=featured?a170Pct(featured):null;
 const kpis=[['المشاريع النشطة',D.active.length,`${D.projects.length} إجمالي`,'folder','projects','blue',null],['مهام اليوم',D.todayTasks.length,`${todayDone} مكتملة`,'check','day','teal',D.todayTasks.length?Math.round(todayDone/D.todayTasks.length*100):0],['الاجتماعات',D.todayMeet.length,D.todayMeet.find(m=>!m.done)?.time?'القادم '+D.todayMeet.find(m=>!m.done).time:'اليوم','cal','meetings','gold',null],['المستندات الجديدة',D.newDocs.length,'هذا الأسبوع','doc','projects','purple',null]];
 return `<section class="a170-hero" data-a170-mod="hero"><div class="a170-hero-bg" role="img" aria-label="صورة مكة المكرمة"></div><div class="a170-hero-main"><h1>${a170Icon('sun')}${a170Greeting()}، ${esc(first)}</h1><p>لديك ${openToday.length} مهام اليوم و${D.todayMeet.filter(m=>!m.done).length} اجتماعات قادمة</p>${a170Prayer()}</div><div class="a170-hero-side"><div class="a170-clock"><strong data-a170-clock>${a170Fmt({hour:'2-digit',minute:'2-digit',hour12:false})}</strong><span>${a170Fmt({weekday:'long'})}<br>${a170Fmt({day:'numeric',month:'long',year:'numeric'})}</span></div><p class="a170-quote">«كل خطوة صغيرة .. تبني فرقاً كبيراً»</p></div>
 <div class="a170-kpis">${kpis.map(([l,n,s,ic,r,c,bar])=>`<button type="button" class="a170-kpi ${c}" data-a170-go="${r}"><span class="a170-kpi-ic">${a170Icon(ic)}</span><span class="a170-kpi-l">${l}</span><strong>${n}</strong><small>${s}</small>${bar!==null?`<i class="a170-kpi-bar"><i style="width:${bar}%"></i></i>`:''}</button>`).join('')}</div>
 <div class="a170-feature">${featured?`<button type="button" class="a170-feature-card" data-a170-project="${esc(featured.id)}"><img src="${img.src}" alt="" loading="lazy"><span><em>المشروع الرئيسي</em><b>${esc(featured.name)}</b><small>${esc(featured.client||'')}</small><span class="a170-bar"><i style="width:${fp??0}%"></i></span><strong>${fp===null?'—':fp+'%'}</strong></span></button>`:'<div class="a170-feature-card empty">أضف مشروعاً ليظهر هنا</div>'}${a170WeatherHtml()}</div></section>`}
function a170Calendar(D){const evs=[...D.todayMeet,...D.tasks.filter(x=>x.due===D.t&&x.time)].sort((a,b)=>String(a.time||'').localeCompare(String(b.time||''))).slice(0,6),months=Array.from({length:12},(_,i)=>{const d=new Date;d.setDate(1);d.setMonth(d.getMonth()-11+i);return d.toISOString().slice(0,7)}),cnt=(arr,f)=>months.map(m=>arr.filter(x=>String(f(x)||'').slice(0,7)===m).length),series=[['المهام',cnt(D.done,x=>x.doneAt?h162Date(x.doneAt):x.due),'#2563EB'],['الاجتماعات',cnt(D.meetings,x=>x.due),'#F59E0B'],['المشاريع',cnt(D.projects,x=>x.start||x.at&&h162Date(x.at)),'#10B981']],max=Math.max(1,...series.flatMap(s=>s[1]));
 const kind=x=>x.kind==='meeting'?(/teams|zoom|meet|أونلاين/i.test((x.loc||'')+(x.title||''))?['Teams','teams','blue']:/موقع|زيارة/.test(x.title||'')?['موقع','pin','red']:['اجتماع','users','gold']):['مهمة','check','teal'];
 return `<section class="a170-card a170-calendar" data-a170-mod="calendar">${a170Head('تقويمي اليوم','meetings',`<button type="button" class="a170-ic" data-a170-go="day" aria-label="فتح أعمال اليوم">${a170Icon('cal')}</button>`)}<div class="a170-daybar"><b>${a170Fmt({day:'numeric',month:'long',year:'numeric'})}</b><span>${a170Fmt({weekday:'long'})}</span></div><div class="a170-timeline">${evs.map(x=>{const [l,ic,c]=kind(x);return `<button type="button" class="a170-ev ${c}" data-a170-task="${esc(x.id)}"><time>${esc(x.time||'')}</time><span><b>${esc(x.title)}</b><small>${esc(x.project||'')}</small></span><em>${a170Icon(ic)}${l}</em></button>`}).join('')||'<p class="a170-empty">لا مواعيد مؤقتة لهذا اليوم.</p>'}</div><div class="a170-chart"><div class="a170-legend">${series.map(([l,,c])=>`<span><i style="background:${c}"></i>${l}</span>`).join('')}</div><div class="a170-bars">${months.map((m,i)=>`<div title="${m}"><span>${series.map(([l,v,c])=>`<i style="height:${Math.round(v[i]/max*100)}%;background:${c}" aria-label="${l} ${v[i]}"></i>`).join('')}</span><small>${new Intl.DateTimeFormat('ar',{month:'short'}).format(new Date(m+'-15'))}</small></div>`).join('')}</div></div></section>`}
function a170Projects(D){const list=(D.active.length?D.active:D.projects).slice(0,4);return `<section class="a170-card a170-projects" data-a170-mod="projects">${a170Head('مشاريعي النشطة','projects')}<div class="a170-proj-grid">${list.map(p=>{const v=a170Pct(p),im=a170ProjImg(p),tags=(typeof ptypes==='function'?ptypes(p):[]).slice(0,2);return `<button type="button" class="a170-proj" data-a170-project="${esc(p.id)}"><span class="a170-proj-img"><img src="${im.src}" alt="" loading="lazy">${im.real?'':'<em>صورة توضيحية</em>'}</span><span class="a170-proj-body"><b>${esc(p.name)}</b><small>${esc(p.client||'')}</small><span class="a170-prog"><span class="a170-bar"><i style="width:${v??0}%"></i></span><strong>${v===null?'—':v+'%'}</strong></span><span class="a170-tags">${tags.map(t=>`<i>${esc(t)}</i>`).join('')}<i class="st">${esc(PSTL[p.status]?.l||'')}</i></span></span></button>`}).join('')||'<p class="a170-empty">لا توجد مشاريع نشطة ضمن صلاحياتك.</p>'}</div></section>`}
function a170Tasks(D){const open=D.todayTasks,f={all:open,mid:open.filter(x=>x.priority===1),high:open.filter(x=>x.priority===2),normal:open.filter(x=>!x.priority)},shown=(f[a170TaskFilter]||open).slice(0,6),lbl=x=>x.done?['منجزة','done']:x.priority===2?['عاجل','high']:x.priority===1?['هام','mid']:x.due<D.t?['متأخرة','late']:['عادي','normal'];
 return `<section class="a170-card a170-tasks" data-a170-mod="tasks">${a170Head('مهامي اليوم','day')}<div class="a170-tabs" role="tablist">${[['all','الكل'],['mid','هام'],['high','عاجل'],['normal','عادي']].map(([k,l])=>`<button type="button" role="tab" data-a170-filter="${k}" aria-selected="${a170TaskFilter===k}">${l}<b>${f[k].length}</b></button>`).join('')}</div><div class="a170-task-list">${shown.map(x=>{const [l,c]=lbl(x);return `<button type="button" class="a170-task${x.done?' isdone':''}" data-a170-task="${esc(x.id)}"><i class="a170-chk" aria-hidden="true">${x.done?a170Icon('check'):''}</i><span><b>${esc(x.title)}</b><small>${esc(x.project||'عام')}${x.time?' · '+esc(x.time):''}</small></span><em class="${c}">${l}</em></button>`}).join('')||'<p class="a170-empty">لا مهام مطابقة. يومك واضح.</p>'}</div><button type="button" class="a170-add" data-a170-new>${a170Icon('plus')}إضافة مهمة</button></section>`}
function a170Performance(D){const pct=D.tasks.length?Math.round(D.done.length/D.tasks.length*100):0,days=Array.from({length:30},(_,i)=>iso(addDays(new Date,i-29))),v=days.map(d=>D.done.filter(x=>x.doneAt&&h162Date(x.doneAt)===d).length),mx=Math.max(1,...v);
 return `<section class="a170-card a170-performance" data-a170-mod="performance">${a170Head('مؤشرات الأداء','dash')}<div class="a170-stats">${[['folder',D.active.length,'مشروع نشط','blue'],['check',pct+'%','نسبة الإنجاز','green'],['grid',D.done.length,'مهمة مكتملة','indigo'],['cal',D.todayMeet.length,'اجتماعات اليوم','red']].map(([ic,n,l,c])=>`<div class="${c}">${a170Icon(ic)}<b>${n}</b><small>${l}</small></div>`).join('')}</div><div class="a170-spark" aria-label="المهام المنجزة خلال 30 يوماً">${v.map((n,i)=>`<i style="height:${Math.max(4,Math.round(n/mx*100))}%" title="${days[i]}: ${n}"></i>`).join('')}</div><small class="a170-cap">المهام المنجزة يومياً خلال آخر 30 يوماً</small></section>`}
function a170DocIc(n){const e=String(n||'').split('.').pop().toLowerCase();return ({pdf:['PDF','red'],doc:['W','blue'],docx:['W','blue'],xls:['X','green'],xlsx:['X','green'],zip:['ZIP','orange'],rar:['ZIP','orange'],dwg:['DWG','indigo'],png:['IMG','teal'],jpg:['IMG','teal'],jpeg:['IMG','teal']})[e]||['FILE','slate']}
function a170Documents(D){return `<section class="a170-card a170-documents" data-a170-mod="documents">${a170Head('المستندات الحديثة','projects')}<div class="a170-doc-list">${D.docs.slice(0,5).map(({p,d})=>{const [t,c]=a170DocIc(d.name||d.url),u=String(d.url||d.link||'');return `<div class="a170-doc"><span class="a170-doc-ic ${c}">${t}</span><button type="button" data-a170-project="${esc(p.id)}" data-a170-section="docs"><b>${esc(d.name||'مستند')}</b><small>${esc(p.name)}${d.at?' · '+esc(h162Date(d.at)):''}</small></button>${/^https?:\/\//i.test(u)?`<a class="a170-ic" href="${esc(u)}" target="_blank" rel="noopener" aria-label="تنزيل">${a170Icon('dl')}</a>`:''}</div>`}).join('')||'<p class="a170-empty">لم تُرفع مستندات للمشاريع المتاحة لك.</p>'}</div></section>`}
function a170Notes(){const n=Array.isArray(yw161Prefs.a170Notes)?yw161Prefs.a170Notes:[];return `<section class="a170-card a170-notes" data-a170-mod="notes">${a170Head('ملاحظاتي السريعة','',`<button type="button" class="a170-ic solid" data-a170-note-focus aria-label="إضافة ملاحظة">${a170Icon('plus')}</button>`)}<ul class="a170-note-list">${n.map((x,i)=>`<li class="${x.d?'isdone':''}"><label><input type="checkbox" data-a170-note="${i}" ${x.d?'checked':''}><span>${esc(x.t)}</span></label><button type="button" data-a170-note-del="${i}" aria-label="حذف">×</button></li>`).join('')||'<li class="a170-empty">لا ملاحظات بعد.</li>'}</ul><form class="a170-note-form" data-a170-note-form><input name="t" maxlength="140" placeholder="إضافة ملاحظة جديدة…" aria-label="ملاحظة جديدة"><button type="submit" class="a170-ic" aria-label="حفظ">${a170Icon('edit')}</button></form><small class="a170-cap">محفوظة لحسابك في هذا المتصفح</small></section>`}
function a170Coords(p){const s=String(p.loc||''),m=s.match(/@?(-?\d{1,2}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/);return m?[+m[1],+m[2]]:null}
function a170Locations(D){const withC=D.projects.map(p=>({p,c:a170Coords(p)})),pins=withC.filter(x=>x.c),rest=withC.filter(x=>!x.c&&x.p.loc).slice(0,3);return `<section class="a170-card a170-locations" data-a170-mod="locations">${a170Head('مواقع المشاريع','projects')}<div class="a170-map" data-a170-map='${esc(JSON.stringify(pins.map(x=>({id:x.p.id,n:x.p.name,c:x.c}))))}'><div class="a170-map-fallback">${a170Icon('pin')}<span>${pins.length?'جارٍ تحميل الخريطة…':'أضف إحداثيات الموقع (مثل 21.42,39.82) في حقل الموقع بملف المشروع لتظهر على الخريطة.'}</span></div></div>${rest.length?`<div class="a170-loc-list">${rest.map(({p})=>`<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.loc)}" target="_blank" rel="noopener">${a170Icon('pin')}<b>${esc(p.name)}</b><small>${esc(p.loc)}</small></a>`).join('')}</div>`:''}</section>`}
function a170Assistant(){return `<section class="a170-card a170-assistant" data-a170-mod="assistant">${a170Head('مساعد يومي الذكي','ai',`<span class="a170-ai-badge">${a170Icon('spark')}</span>`)}<div class="a170-tabs small">${['مساعد المشاريع','تحليل المستندات','أفكار وتوصيات'].map((l,i)=>`<button type="button" data-a170-go="ai" aria-selected="${i===0}">${l}</button>`).join('')}</div><div class="a170-ai-msg"><p>مرحباً ${esc(String(ME.name||'').split(' ')[0])}، يمكنني مساعدتك في:</p><ul><li>تلخيص المستندات والعقود</li><li>تحليل مخططات المشاريع</li><li>اقتراح خطة عمل</li><li>إعداد تقارير احترافية</li></ul></div><form class="a170-ai-form" data-a170-ai><input name="q" placeholder="اكتب سؤالك هنا…" aria-label="سؤال للمساعد"><button type="submit" class="a170-ic solid" aria-label="إرسال">${a170Icon('send')}</button></form></section>`}
function a170Team(D){const users=can('team')?USERS.filter(u=>u.active!==false).slice(0,5):USERS.filter(u=>u.id===ME.id);return `<section class="a170-card a170-team" data-a170-mod="team">${a170Head('توزيع المهام على الفريق',can('team')?'team':'')}<div class="a170-people">${users.map(u=>{const a=D.tasks.filter(x=>x.owner===u.id),c=a.filter(x=>x.done).length,r=a.length?Math.round(c/a.length*100):0;return `<div class="a170-person"><span class="a170-av">${esc(String(u.name||'').trim().slice(0,1))}</span><span class="a170-pn"><b>${esc(u.name||'')}</b><small>${esc(u.title||ROLEL[u.role]||'')}</small></span><span class="a170-bar ${r<50?'low':''}"><i style="width:${r}%"></i></span><b>${r}%</b><small>${c}/${a.length}</small></div>`}).join('')||'<p class="a170-empty">لا توجد تكليفات متاحة.</p>'}</div></section>`}
function a170Pictures(D){const real=D.projects.flatMap(p=>(p.docs||[]).filter(d=>/\.(png|jpe?g|webp)(\?|$)/i.test(String(d.url||''))).map(d=>({p,src:d.url,cap:d.name||p.name,at:d.at||0}))).sort((a,b)=>b.at-a.at).slice(0,8);return real.length?real:(isDemo?[{p:D.projects[0],src:'assets/hybrid/project.jpg',cap:'صورة توضيحية — ليست صورة فعلية',demo:true}]:[])}
