function a171Menu(id,btn){document.querySelector('.a171-pop')?.remove();const p=PV().find(x=>x.id===id);if(!p)return;const m=document.createElement('div');m.className='a171-pop';m.innerHTML=`<button type="button" data-a171-img="${esc(id)}">📷 تغيير صورة المشروع</button><button type="button" data-a171-imgurl="${esc(id)}">🔗 صورة من رابط</button>${p.img?`<button type="button" data-a171-imgdel="${esc(id)}">🗑️ إزالة الصورة</button>`:''}<button type="button" data-a171-pin="${esc(id)}">📍 تحديد الموقع على الخريطة</button><button type="button" data-a170-project="${esc(id)}">فتح المشروع</button>`;document.body.append(m);const r=btn.getBoundingClientRect();m.style.top=(r.bottom+window.scrollY+4)+'px';m.style.left=Math.max(8,r.left+window.scrollX-150)+'px';setTimeout(()=>document.addEventListener('click',function c(e){if(!m.contains(e.target)){m.remove();document.removeEventListener('click',c)}}),0)}
async function a171Save(id,change,msg){const p=PV().find(x=>x.id===id);if(!p)return;if(!pEdit()||!canWrite){toast('لا تملك صلاحية تعديل المشروع');return}try{await j149SaveProject(p,change);toast(msg);render()}catch(e){toast('تعذر الحفظ: '+(e.message||e))}}
function a171Resize(file){return new Promise((ok,no)=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const W=360,H=270,c=document.createElement('canvas');c.width=W;c.height=H;const g=c.getContext('2d'),s=Math.max(W/im.width,H/im.height),w=im.width*s,h=im.height*s;g.drawImage(im,(W-w)/2,(H-h)/2,w,h);let q=.7,d=c.toDataURL('image/jpeg',q);while(d.length>30000&&q>.3){q-=.1;d=c.toDataURL('image/jpeg',q)}ok(d)};im.onerror=no;im.src=fr.result};fr.onerror=no;fr.readAsDataURL(file)})}
let a171PinFor=null;
document.addEventListener('click',async e=>{const t=e.target.closest('[data-a171-menu],[data-a171-img],[data-a171-imgurl],[data-a171-imgdel],[data-a171-pin],[data-a171-pincancel]');if(!t)return;e.preventDefault();e.stopPropagation();const d=t.dataset;
 if(d.a171Menu){a171Menu(d.a171Menu,t);return}
 document.querySelector('.a171-pop')?.remove();
 if(d.a171Img){const i=document.createElement('input');i.type='file';i.accept='image/*';i.onchange=async()=>{const f=i.files[0];if(!f)return;try{const u=await a171Resize(f);a171Save(d.a171Img,x=>{x.img=u},'تم حفظ صورة المشروع')}catch{toast('تعذرت قراءة الصورة')}};i.click();return}
 if(d.a171Imgurl){const u=prompt('الصق رابط صورة مباشر (يبدأ بـ https)');if(u&&/^https:\/\//.test(u.trim()))a171Save(d.a171Imgurl,x=>{x.img=u.trim()},'تم حفظ صورة المشروع');else if(u)toast('الرابط يجب أن يبدأ بـ https');return}
 if(d.a171Imgdel){a171Save(d.a171Imgdel,x=>{delete x.img},'أزيلت صورة المشروع');return}
 if(d.a171Pin){a171PinFor=d.a171Pin;const p=PV().find(x=>x.id===a171PinFor);toast('اضغط على الخريطة لتحديد موقع «'+(p?.name||'')+'»');const card=document.querySelector('.a170-locations');card?.scrollIntoView({behavior:'smooth',block:'center'});card?.classList.add('a171-picking');a171EnsureMap(true);return}
 if(t.hasAttribute('data-a171-pincancel')){a171PinFor=null;document.querySelector('.a170-locations')?.classList.remove('a171-picking');return}
},true);
// الخريطة تظهر دائماً (مكة كمركز افتراضي) ويمكن تحديد موقع مشروع بالضغط عليها
const a171LocBase=a170Locations;a170Locations=function(D){let h=a171LocBase(D);const can2=pEdit()&&canWrite&&D.projects.length;const sel=can2?`<div class="a171-pinbar"><select data-a171-pinsel aria-label="مشروع لتحديد موقعه"><option value="">📍 حدد موقع مشروع…</option>${D.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${a170Coords(p)?' ✓':''}</option>`).join('')}</select><button type="button" data-a171-pincancel>إلغاء</button><span>اضغط على الخريطة لتثبيت الموقع</span></div>`:'';return h.replace('<div class="a170-map"',sel+'<div class="a170-map" data-a171-always="1"')};
document.addEventListener('change',e=>{const s=e.target.closest('[data-a171-pinsel]');if(!s)return;a171PinFor=s.value||null;document.querySelector('.a170-locations')?.classList.toggle('a171-picking',!!a171PinFor);if(a171PinFor)a171EnsureMap(true)});
let a171MapObj=null;
function a171EnsureMap(force){const el=document.querySelector('.a170-map[data-a170-map]');if(!el)return;if(el.dataset.ready&&!force)return;if(el.dataset.ready&&el._map){return}el.dataset.ready='1';let pins=[];try{pins=JSON.parse(el.dataset.a170Map)}catch{}
 const go=()=>{try{el.innerHTML='';const map=L.map(el,{zoomControl:true}).setView(pins[0]?.c||[21.4225,39.8262],pins.length?11:10);el._map=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);const b=[];for(const x of pins){L.marker(x.c).addTo(map).bindTooltip(x.n,{permanent:true,direction:'top'}).on('click',()=>{const p=PV().find(y=>y.id===x.id);if(p)goTab('projects',()=>{projOpen=p.id;projDraft=null;projSec='info';render()})});b.push(x.c)}if(b.length>1)map.fitBounds(b,{padding:[30,30]});
  map.on('click',ev=>{if(!a171PinFor)return;const id=a171PinFor,ll=[+ev.latlng.lat.toFixed(6),+ev.latlng.lng.toFixed(6)];a171PinFor=null;a171Save(id,x=>{x.geo=ll},'تم تثبيت موقع المشروع على الخريطة')})}catch{}};
 if(window.L)return go();if(!document.querySelector('#a170-leaflet-css')){const l=document.createElement('link');l.id='a170-leaflet-css';l.rel='stylesheet';l.href='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css';document.head.append(l)}const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js';s.onload=go;document.head.append(s)}
a170InitMap=function(){a171EnsureMap(false)};
// اختصار لوحة المفاتيح: N = إنشاء جديد (خارج حقول الكتابة)
document.addEventListener('keydown',e=>{if(e.key!=='n'&&e.key!=='N'&&e.key!=='ى')return;if(e.ctrlKey||e.metaKey||e.altKey)return;const t=e.target;if(t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)))return;if(!document.documentElement.hasAttribute('data-a170'))return;const b=document.querySelector('#a170New');if(b){e.preventDefault();b.click()}});

// v172 — صور المشاريع في صفحة المشاريع + معاينة كل واجهة وتجربتها قبل اعتمادها. طبقة عرض فقط.
function a172Cover(){if(!document.documentElement.hasAttribute('data-a170'))return;document.querySelectorAll('#view .p143-card[data-p143-card]:not([data-a172])').forEach(card=>{card.dataset.a172='1';const p=PV().find(x=>x.id===card.dataset.p143Card);if(!p)return;const im=a170ProjImg(p),v=a170Pct(p),d=document.createElement('div');d.className='a172-cover';d.innerHTML=`<img src="${esc(im.src)}" alt="" loading="lazy">${im.real?'':'<em>صورة توضيحية</em>'}${v===null||v===undefined?'':`<span class="a172-pct">${v}%</span>`}`;card.prepend(d)})}
const a172ApplyBase=yw161Apply;yw161Apply=function(){a172ApplyBase();try{a172Cover()}catch{}};
// ---- المعاينة ----
const A172_PREV='assets/previews-v172/';
function a172Thumbs(dialog){dialog.querySelectorAll('.yw161-choice').forEach(l=>{if(l.querySelector('.a172-thumb'))return;const id=l.querySelector('input[name=template]')?.value;if(!id)return;const img=document.createElement('img');img.className='a172-thumb';img.loading='lazy';img.alt='معاينة '+id;img.src=A172_PREV+id+'.jpg';img.onerror=()=>img.remove();img.addEventListener('click',e=>{e.preventDefault();a172Zoom(id)});l.prepend(img);const sp=l.querySelector('span');if(sp&&!sp.querySelector('.a172-try')){const b=document.createElement('button');b.type='button';b.className='a172-try';b.textContent='👁 معاينة وتجربة';b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();a172Zoom(id)});sp.append(b)}})}
function a172Name(id){return (YW161_TEMPLATES.find(t=>t.id===id)||{}).name||id}
function a172Zoom(id){document.querySelector('.a172-zoom')?.remove();const z=document.createElement('div');z.className='a172-zoom';z.innerHTML=`<figure><img src="${A172_PREV+id}-l.jpg" alt="معاينة ${esc(a172Name(id))}" onerror="this.src='${A172_PREV+id}.jpg'"><figcaption><b>${esc(a172Name(id))}</b><div><button type="button" class="pri" data-a172-trial="${esc(id)}">جرّبها الآن على بياناتي</button><button type="button" class="sec" data-a172-close>إغلاق</button></div></figcaption></figure>`;(document.querySelector('#yw161-dialog[open]')||document.body).append(z);z.addEventListener('click',e=>{if(e.target===z||e.target.closest('[data-a172-close]'))z.remove()})}
let a172Prev=null;
function a172Trial(id){yw161Load();if(!a172Prev)a172Prev={...yw161Prefs};yw161Prefs={...yw161Prefs,template:id};document.querySelector('#yw161-dialog')?.close?.();document.querySelector('.a172-zoom')?.remove();yw161Apply();const t=YW161_TEMPLATES.find(x=>x.id===id);try{yw161Go(t||{start:'home'})}catch{}try{render()}catch{}document.querySelector('.a172-trial')?.remove();const bar=document.createElement('div');bar.className='a172-trial';bar.innerHTML=`<span>تجربة: <b>${esc(a172Name(id))}</b> — لم تُحفظ بعد</span><button type="button" class="keep" data-a172-keep>اعتماد هذه الواجهة</button><button type="button" class="back" data-a172-back>رجوع للسابقة</button>`;document.body.append(bar)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-a172-trial],[data-a172-keep],[data-a172-back]');if(!t)return;e.preventDefault();
 if(t.dataset.a172Trial){a172Trial(t.dataset.a172Trial);return}
 if(t.hasAttribute('data-a172-keep')){a172Prev=null;yw161Save();document.querySelector('.a172-trial')?.remove();toast('تم اعتماد الواجهة لحسابك');return}
 if(t.hasAttribute('data-a172-back')){if(a172Prev){yw161Prefs=a172Prev;a172Prev=null;yw161Apply();try{render()}catch{}}document.querySelector('.a172-trial')?.remove();toast('رجعت للواجهة السابقة');return}
});
const a172OpenBase=yw161Open;yw161Open=function(){a172OpenBase();const d=document.querySelector('#yw161-dialog');if(d){a172Thumbs(d);const h=d.querySelector('.yw161-head p');if(h&&!h.dataset.a172){h.dataset.a172=1;h.textContent+=' اضغط صورة أي واجهة لمعاينتها وتجربتها على بياناتك قبل اعتمادها.'}}};

// END APPEARANCE V161
